edad = int(input("Ingresa tu edad:"))
if edad >= 6 and edad <= 17:
    print("Se recomienda un promedio de 60 minutos diarios de actividad física , principalmente aeróbica y de intensidad moderada a vigorosa, para los niños y adolescentes de 6 a 17 años.")
if edad >= 18 and edad <= 64:
    print("Se recomienda un promedio de 150 a 300 minutos semanales de actividad física aeróbica de intensidad moderada, o 75 a 150 minutos semanales de actividad física aeróbica de intensidad vigorosa, o una combinación equivalente de actividad física moderada y vigorosa, para los adultos de 18 a 64 años.")
if edad >= 65 and edad <= 100:
    print("Se recomienda un promedio de 150 a 300 minutos semanales de actividad física aeróbica de intensidad moderada, o 75 a 150 minutos semanales de actividad física aeróbica de intensidad vigorosa, o una combinación equivalente de actividad física moderada y vigorosa, para los adultos mayores de 65 años.")
